function buildTree(){
 $('boneTree').innerHTML=GROUPS.map(g=>`<section class="bone-group" data-group="${g.id}" style="--group-color:${g.color}"><div class="group-header" role="button" tabindex="0" aria-expanded="true"><span class="group-caret">▾</span><span class="group-dot"></span><strong>${g.name}</strong><small>${groupPinyin(g)} · ${g.count}</small><button class="group-visibility" data-group-eye="${g.id}" title="切换${g.name}可见性" aria-label="切换${g.name}可见性">${icon('eye')}</button></div><div class="group-list">${BONES.filter(b=>b.group===g.id).map(b=>`<div class="bone-row" data-bone="${b.id}"><button class="bone-select" data-select="${b.id}" title="${b.name} · ${b.en}"><span>${b.name}</span>${bonePinyin(b)?`<span class="short-pinyin">${bonePinyin(b)}</span>`:''}</button><button class="bone-eye" data-eye="${b.id}" title="隐藏 ${b.name}" aria-label="隐藏 ${b.name}">${icon('eye')}</button></div>`).join('')}</div></section>`).join('');
 $('boneTree').querySelectorAll('.group-header').forEach(el=>{const toggle=()=>{el.parentElement.classList.toggle('collapsed');el.setAttribute('aria-expanded',String(!el.parentElement.classList.contains('collapsed')));};el.addEventListener('click',e=>{if(!e.target.closest('[data-group-eye]'))toggle();});el.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===el){e.preventDefault();toggle();}});});
 $('boneTree').querySelectorAll('[data-select]').forEach(el=>el.addEventListener('click',()=>selectBone(el.dataset.select,true,true)));
 $('boneTree').querySelectorAll('[data-eye]').forEach(el=>el.addEventListener('click',()=>toggleBone(el.dataset.eye)));
 $('boneTree').querySelectorAll('[data-group-eye]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();const ids=BONES.filter(b=>b.group===el.dataset.groupEye).map(b=>b.id),allHidden=ids.every(id=>state.hidden.has(id));ids.forEach(id=>allHidden?state.hidden.delete(id):state.hidden.add(id));if(state.isolated)exitIsolate(false);applyVisibility();updateTree();}));
 $('search').addEventListener('input',()=>{const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f\s·]/g,'');const q=normalize($('search').value.trim());const pinyin={talus:'jugu',calcaneus:'gengu',navicular:'zhougu',cuboid:'tougu',tarsal:'fugu',metatarsal:'zhigu',phalanges:'zhigu',sesamoid:'zigu',coccyx:'weigu',pelvis:'gupen'};let total=0;document.querySelectorAll('.bone-row').forEach(row=>{const b=BY_ID[row.dataset.bone],hit=!q||normalize([b.name,b.en,bonePinyin(b),pinyin[b.id]||'',pinyin[b.group]||'',b.id.includes('cuneiform')?'xiegu':''].join(' ')).includes(q);row.hidden=!hit;if(hit)total++;});document.querySelectorAll('.bone-group').forEach(group=>{group.hidden=![...group.querySelectorAll('.bone-row')].some(r=>!r.hidden);if(q){group.classList.remove('collapsed');group.querySelector('.group-header').setAttribute('aria-expanded','true');}});$('boneTree').querySelector('.empty-search')?.remove();if(!total){const d=document.createElement('div');d.className='empty-search';d.textContent='没有找到这个骨名';$('boneTree').append(d);}});
}
function updateTree(){document.querySelectorAll('.bone-row').forEach(row=>{const id=row.dataset.bone,b=bones.get(id);row.classList.toggle('active',state.selected===id);row.classList.toggle('is-hidden',state.hidden.has(id));row.classList.toggle('is-moved',!!b&&isManuallyMoved(b));row.querySelector('[data-select]').setAttribute('aria-pressed',String(state.selected===id));row.querySelector('[data-eye]').title=`${state.hidden.has(id)?'显示':'隐藏'} ${BY_ID[id].name}`;row.querySelector('[data-eye]').setAttribute('aria-label',row.querySelector('[data-eye]').title);});document.querySelectorAll('[data-group-eye]').forEach(el=>el.classList.toggle('off',BONES.filter(b=>b.group===el.dataset.groupEye).every(b=>state.hidden.has(b.id))));const moved=[...bones.values()].filter(isManuallyMoved).length;$('movedCount').hidden=!moved;$('movedCount').textContent=`已操作 ${moved} 块`;$('hideSelectedBtn').innerHTML=`${icon('eye')}${state.hidden.has(state.selected)?'显示本骨':'隐藏本骨'}`;}
function selectBone(id,fromList=false,announce=false){invalidate();if(!BY_ID[id])return;revealBone(id);state.selected=id;state.hidden.delete(id);const b=BY_ID[id],g=GROUPS.find(g=>g.id===b.group);$('boneIndex').textContent=`${String(b.index).padStart(2,'0')} / 210`;$('detailTitle').innerHTML=`<span class="group-tag">${g.name}${g.id==='tarsal'?' · fū gǔ':''} <span> / </span> ${b.region}</span><h2 class="${b.name.length>6?'long-name':''}">${b.name}${bonePinyin(b)?`<small>${bonePinyin(b)}</small>`:''}</h2><p>${b.en}</p>`;$('description').textContent=b.description;$('look').textContent=b.look;$('studyTip').textContent=b.tip;$('neighbors').innerHTML=b.neighbors.map(n=>`<button data-neighbor="${n}" title="查看 ${BY_ID[n].name}">${BY_ID[n].name}</button>`).join('');$('neighbors').querySelectorAll('button').forEach(el=>el.addEventListener('click',()=>selectBone(el.dataset.neighbor,true,true)));needsLabelRebuild=true;applyVisibility();updateTree();updatePreview();if(state.isolated)fitToContent(true);if(!fromList){const row=document.querySelector(`[data-bone="${id}"]`),group=row?.closest('.bone-group');if(group){group.classList.remove('collapsed');group.querySelector('.group-header').setAttribute('aria-expanded','true');}row?.scrollIntoView({block:'nearest',behavior:'smooth'});}window.dispatchEvent(new CustomEvent('atlas:bone-selected',{detail:{id,user:announce}}));}
function toggleBone(id){if(!state.ready)return;if(state.isolated)exitIsolate(false);state.hidden.has(id)?state.hidden.delete(id):state.hidden.add(id);applyVisibility();updateTree();}
function makeBoneMaterial(){const mat=new THREE.MeshStandardMaterial({color:'#e3dac6',roughness:.78,metalness:0,envMapIntensity:.42});mat.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 vBonePosition;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvBonePosition = position;');shader.fragmentShader='varying vec3 vBonePosition;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>',`#include <color_fragment>\nfloat grain = sin(vBonePosition.x * 10.13 + sin(vBonePosition.z * 9.71)) * sin(vBonePosition.y * 11.37 + vBonePosition.z * 6.7);\ndiffuseColor.rgb *= 0.985 + 0.015 * grain;`);};mat.customProgramCacheKey=()=> 'foot-atlas-bone-v1';return mat;}
function applyVisibility(){invalidate();const neighbors=new Set(BY_ID[state.selected]?.neighbors||[]);let visible=0;for(const [id,b]of bones){b.visible=state.bonesOn&&!state.tissueIsolated&&!state.hidden.has(id)&&regionContains(id)&&(!state.isolated||id===state.selected);if(b.visible)visible++;let color=state.colors?GROUPS.find(g=>g.id===BY_ID[id].group).color:'#e3dac6';if(id===state.selected)color='#8ab3a1';else if(id===hoveredId)color='#c6d6bc';else if(state.neighbors&&neighbors.has(id))color='#c1d3a6';b.material.color.set(color);const faded=state.neighbors&&id!==state.selected&&!neighbors.has(id);b.material.opacity=(faded?.13:1)*(state.isolated?1:(state.boneOpacity??1));b.material.transparent=b.material.opacity<.99;b.material.depthWrite=b.material.opacity>=.99;b.material.emissive.set(id===state.selected?'#234c3b':'#000000');b.material.emissiveIntensity=id===state.selected?.045:0;b.material.needsUpdate=true;b.castShadow=!faded;}$('visibleCount').textContent=`${visible} / 210 可见`;$('neighborsBtn').classList.toggle('active',state.neighbors);$('neighborsBtn').setAttribute('aria-pressed',String(state.neighbors));$('isolateBtn').innerHTML=state.isolated?`${icon('layers')}返回区域`:`${icon('focus')}单独查看`;$('isolateBanner').hidden=!state.isolated;needsLabelRebuild=true;updateGhosts();if(state.ready)updateLabels();}
function updatePreview(){if(!previewRenderer||!bones.has(state.selected))return;if(previewMesh){previewScene.remove(previewMesh);previewMesh.material.dispose();}const b=bones.get(state.selected);previewMesh=new THREE.Mesh(b.geometry,new THREE.MeshStandardMaterial({color:'#d9d5be',roughness:.73,metalness:0}));previewScene.add(previewMesh);previewMesh.geometry.computeBoundingSphere();const radius=Math.max(previewMesh.geometry.boundingSphere.radius,2);previewControls.target.set(0,0,0);const distance=radius/Math.sin(THREE.MathUtils.degToRad(previewCamera.fov/2))/Math.min(previewCamera.aspect||1,1)*1.16;previewCamera.position.copy(new THREE.Vector3(1,.75,1.2).normalize().multiplyScalar(distance));previewCamera.near=Math.max(radius/100,.01);previewCamera.far=radius*60;previewCamera.updateProjectionMatrix();previewControls.minDistance=radius*1.4;previewControls.maxDistance=distance*3;previewControls.update();}
function baselineExplosion(id,home){const b=BY_ID[id],v=new THREE.Vector3();if(b.group==='pelvis'){const d={'hip-right':[-140,20,35],'hip-left':[140,20,35],sacrum:[0,100,-120],coccyx:[0,-50,-170]};return v.fromArray(d[id]);}if(id==='femur')return v.set(0,130,-40);if(id==='patella')return v.set(75,5,115);if(b.group==='leg')return v.set(id==='tibia'?95:-110,id==='tibia'?75:30,-25);if(b.group==='tarsal'){const table={talus:[10,84,-25],calcaneus:[0,-16,-68],navicular:[28,39,0],cuboid:[-66,3,-9],'cuneiform-medial':[72,22,32],'cuneiform-intermediate':[7,55,42],'cuneiform-lateral':[-34,27,33]};return v.fromArray(table[id]);}if(b.group==='sesamoid')return v.set(home.x*1.4+(id.endsWith('medial')?18:-2),-55,75);const toe=Number(id.split('-').at(-1)),x=(3-toe)*30;if(b.group==='metatarsal')return v.set(x,8+(toe%2)*8,72);const part=id.split('-')[0];return v.set(x*1.45,part==='proximal'?2:part==='middle'?12:24,part==='proximal'?122:part==='middle'?155:188);}
const PATIENT_MIDLINE_X=99.55318155698478;
const SPINE_SEQUENCE=[...Array.from({length:7},(_,i)=>`C${i+1}`),...Array.from({length:12},(_,i)=>`T${i+1}`),...Array.from({length:5},(_,i)=>`L${i+1}`)];
function spineExplosion(id){
 let seq=SPINE_SEQUENCE.filter(x=>regionContains(x)&&bones.has(x));
 if(['spine','lumbosacral'].includes(state.region))seq.push(...['sacrum','coccyx'].filter(x=>regionContains(x)&&bones.has(x)));
 if(!seq.includes(id)||seq.length<2)return new THREE.Vector3();
 // Stack original bounding surfaces, not alternating vectors. At 100%, every
 // adjacent pair has a positive vertical gap, while its X/Z and rotation stay fixed.
 const gap=seq.length<=7?23:17, target=[bones.get(seq[0]).userData.home.y];
 for(let i=1;i<seq.length;i++){
  const prev=bones.get(seq[i-1]),cur=bones.get(seq[i]);
  target[i]=target[i-1]+prev.geometry.boundingBox.min.y-cur.geometry.boundingBox.max.y-gap;
 }
 const bottomAnchored=['body','all','pelvic-limb','lumbosacral'].includes(state.region);
 const shift=bottomAnchored?bones.get(seq.at(-1)).userData.home.y-target.at(-1):
  (bones.get(seq[0]).userData.home.y+bones.get(seq.at(-1)).userData.home.y-target[0]-target.at(-1))/2;
 const i=seq.indexOf(id);return new THREE.Vector3(0,target[i]+shift-bones.get(id).userData.home.y,0);
}
function explosionVector(id,home){
 const b=BY_ID[id],sgn=b.side==='left'?1:-1;
 if(['cervical','thoracic','lumbar'].includes(b.group)||(['sacrum','coccyx'].includes(id)&&['spine','lumbosacral'].includes(state.region)))return spineExplosion(id);
 if(b.group==='thorax'){if(id==='sternum')return new THREE.Vector3(0,20,180);const i=Number(id.split('-')[1]);return new THREE.Vector3(sgn*(115+i*7),(7-i)*9,35);}
 if(['cranial','facial'].includes(b.group)){const v=home.clone().sub(new THREE.Vector3(PATIENT_MIDLINE_X,1535,-100));if(v.lengthSq()<1)v.set(0,1,0);return v.normalize().multiplyScalar(b.group==='cranial'?170:110);}
 if(b.group==='head-other')return id==='hyoid'?new THREE.Vector3(0,-75,115):new THREE.Vector3(sgn*(id.startsWith('malleus')?60:id.startsWith('incus')?90:125),15,35);
 if(b.group==='shoulder')return new THREE.Vector3(sgn*195,40,b.baseId==='clavicle'?95:-95);
 if(b.group==='arm')return new THREE.Vector3(sgn*(b.baseId==='humerus'?170:b.baseId==='radius'?225:290),b.baseId==='humerus'?35:-40,45);
 if(HAND_GROUPS.has(b.group)){const i=Number(b.baseId.split('-').at(-1))||1,v=new THREE.Vector3(sgn*(100+i*20),-40,30);if(b.group==='hand-phalanges')v.y-=b.baseId.includes('distal')?125:b.baseId.includes('middle')?88:55;if(b.group==='carpal')v.set(sgn*(75+(BONES.findIndex(x=>x.id===id)%4)*20),12,((BONES.findIndex(x=>x.id===id)%3)-1)*55);return v;}
 let v;
 if(b.side==='left'&&b.group!=='pelvis'){const h=home.clone();h.x=2*PATIENT_MIDLINE_X-h.x;v=baselineExplosion(b.baseId,h);v.x*=-1;}else v=baselineExplosion(id,home);
 if(state.side==='both'&&!['pelvis'].includes(b.group))v.x+=b.side==='left'?115:-115;
 return v;
}
function setExplode(percent,fit=true){invalidate();if(!state.ready)return;state.explode=clamp(Number(percent)||0,0,100);$('explode').value=String(state.explode);$('explode').style.setProperty('--progress',state.explode+'%');$('explodeValue').innerHTML=`${Math.round(state.explode)}<span>%</span>`;document.querySelectorAll('[data-explode-preset]').forEach(el=>el.classList.toggle('active',Number(el.dataset.explodePreset)===Math.round(state.explode)));const note=$('explodeNote');if(note)note.textContent=['cervical','thoracic','lumbar','spine'].includes(state.region)?'按上下轴向分层，完全展开时逐节留出间隙':state.region==='thorax'?'胸廓按左右与前后分层展开':'按解剖方向分层：中轴上下、左右骨向身体两侧';for(const b of bones.values()){b.userData.explosion=regionContains(b.name)?explosionVector(b.name,b.userData.home):new THREE.Vector3();b.position.copy(b.userData.home).addScaledVector(b.userData.explosion,state.explode/100).add(b.userData.offset);}updateGhosts();tissueLayer?.updateFrame();if(fit&&!state.isolated)fitToContent(true);}
function updateGhosts(){for(const [id,b]of bones){const moved=b.position.distanceTo(b.userData.home)>.3||b.quaternion.angleTo(new THREE.Quaternion())>.04,show=state.ghost&&moved&&b.visible&&!state.isolated;const ghost=ghosts.get(id),guide=guides.get(id);if(!ghost||!guide)continue;ghost.visible=show;guide.visible=show&&b.position.distanceTo(b.userData.home)>2;ghost.material.opacity=id===state.selected?.17:.085;if(guide.visible){const arr=guide.geometry.attributes.position;arr.setXYZ(0,...b.userData.home.toArray());arr.setXYZ(1,...b.position.toArray());arr.needsUpdate=true;guide.computeLineDistances();}}}
function isManuallyMoved(b){return b.userData.offset.lengthSq()>.04||b.quaternion.angleTo(new THREE.Quaternion())>.015;}
function resetBones(full=false,options={}){if(full&&!options.keepStudy)learningEnhancements?.clearStudyContext(true);if(!state.ready)return;for(const b of bones.values()){b.userData.offset.set(0,0,0);b.quaternion.identity();}if(full){state.hidden.clear();state.isolated=false;state.neighbors=false;state.ghost=false;state.view='overview';$('ghostBtn').classList.remove('active');$('ghostBtn').setAttribute('aria-pressed','false');setMode('orbit');}setExplode(0,false);applyVisibility();updateTree();if(full)setView('overview');else fitToContent(true);toast('已恢复骨骼的原始位置与朝向');}
function resetSelected(){if(!state.ready)return;const b=bones.get(state.selected);if(!b)return;b.userData.offset.set(0,0,0);b.quaternion.identity();setExplode(state.explode,false);updateTree();if(state.isolated)fitToContent(true);toast(`${BY_ID[state.selected].name}已归位${state.explode?'，保留整体展开程度':''}`);}
function setMode(mode){invalidate();state.mode=mode;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('modeHint').textContent=mode==='move'?'按住骨头直接拖出 · 拖拽空白仍可旋转模型':mode==='rotate'?'按住骨头单独转动 · 拖拽空白仍可旋转模型':'拖拽空白或骨骼旋转模型 · 单击选择一块骨';viewport.style.cursor=mode==='orbit'?'grab':'default';if(controls)controls.enabled=true;}
function toggleIsolate(){if(!state.ready)return;if(state.isolated){exitIsolate();return;}state.isolated=true;state.neighbors=false;state.hidden.delete(state.selected);applyVisibility();fitToContent(true);}
function exitIsolate(refit=true){state.isolated=false;applyVisibility();if(refit)fitToContent(true);}
function toggleNeighbors(){if(!state.ready)return;if(state.isolated)exitIsolate(false);state.neighbors=!state.neighbors;if(state.neighbors)BY_ID[state.selected].neighbors.forEach(id=>state.hidden.delete(id));applyVisibility();updateTree();fitToContent(true);if(state.neighbors)toast('绿色为主要邻接骨；半透明仅是显示效果');}

