// Fixed labels for the user-requested full-body anatomy viewer.
const REGION_LABELS={body:['全身骨骼','Complete skeleton'],head:['头颅与舌骨','Skull & hyoid'],auditory:['听小骨','Auditory ossicles'],cervical:['颈椎 C1—C7','Cervical spine'],thoracic:['胸椎 T1—T12','Thoracic spine'],spine:['脊柱全览','Vertebral column'],thorax:['胸廓','Thoracic cage'],shoulder:['肩部','Shoulders'],upper:['上肢全览','Upper limbs'],elbow:['肘部','Elbows'],wrist:['腕部','Wrists'],hand:['手部','Hands'],foot:['足部','Feet'],ankle:['足踝连接','Ankles'],leg:['小腿与足','Lower legs & feet'],knee:['膝部骨骼','Knees'],whole:['下肢全览','Lower limbs'],hip:['髋部连接','Hip joints'],pelvis:['骨性骨盆','Bony pelvis'],'pelvic-limb':['骨盆与下肢','Pelvis & lower limbs'],lumbar:['腰椎 L1—L5','Lumbar spine'],lumbosacral:['腰骶与骨盆','Lumbosacral & pelvis'],all:['腰椎、骨盆与双下肢','Lumbar spine & lower limbs']};
const UPPER_REGIONS=new Set(Object.keys(REGION_LABELS).filter(x=>!['foot','ankle','leg'].includes(x)));
const FIXED_REGIONS=new Set(['pelvis','lumbar','lumbosacral','cervical','thoracic','spine']);
const LOWER_GROUPS=new Set(['thigh','leg','tarsal','metatarsal','phalanges','sesamoid']);
const HAND_GROUPS=new Set(['carpal','metacarpal','hand-phalanges']);
const ARM_GROUPS=new Set(['shoulder','arm',...HAND_GROUPS]);
const regionNames=Object.fromEntries(Object.entries(REGION_LABELS).map(([k,v])=>[k,v[0]]));

// Membership tables are produced and validated from the fixed bone inventory at build time.
function regionContains(id){
 return Boolean(REGION_MEMBERSHIP[state.region]?.[state.side]?.includes(id));
}
function defaultSelection(){
 const preferred={body:'sternum',head:'frontal',cervical:'C2',thoracic:'T6',spine:'T6',thorax:'sternum',lumbar:'L5',lumbosacral:'L5',pelvis:'sacrum'};
 return preferred[state.region]||BONES.find(b=>regionContains(b.id))?.id||'sternum';
}

function updateRegionUI(){
 scene.background.set('#eff2e9');
 camera.far=UPPER_REGIONS.has(state.region)?24000:6500;camera.updateProjectionMatrix();
 for(const el of document.querySelectorAll('[data-region]')){const active=el.dataset.region===state.region;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));}
 for(const el of document.querySelectorAll('[data-side]')){const active=el.dataset.side===state.side;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));el.disabled=FIXED_REGIONS.has(state.region);}
 const [cn,en]=REGION_LABELS[state.region],suffix=FIXED_REGIONS.has(state.region)?'':state.side==='both'?'双侧':state.side==='right'?'人体右侧':'人体左侧';
 const subtitle=document.createElement('span');subtitle.textContent=en;$('regionHeading').replaceChildren(document.createTextNode(cn+' '),subtitle);
 const count=BONES.filter(b=>regionContains(b.id)).length;
 $('regionHint').textContent=cn+' · '+count+' 个骨块'+(suffix?' · '+suffix:'')+(state.region==='body'?' · 206 标准骨 + 4 籽骨':'');
 $('sideNotice').textContent='左右均指人体自身；正面看：人体右侧在画面左边。';
 const upper=UPPER_REGIONS.has(state.region),globalSide=FIXED_REGIONS.has(state.region)||state.side==='both'||['body','head','thorax','auditory'].includes(state.region);
 document.querySelector('[data-view="dorsal"]').textContent=upper?'上方':'足背';
 document.querySelector('[data-view="plantar"]').textContent=upper?'下方':'足底';
 document.querySelector('[data-view="front"]').textContent=upper?'前面':'趾端';
 document.querySelector('[data-view="medial"]').textContent=globalSide?'人体左面':'内侧';
 document.querySelector('[data-view="lateral"]').textContent=globalSide?'人体右面':'外侧';
}

function matchingSide(b,side){
 return BONES.find(x=>x.baseId===b.baseId&&x.side===side)?.id;
}
function revealBone(id){
 if(!state.ready||regionContains(id))return;
 const item=BY_ID[id];
 state.side=item.side==='midline'?'both':item.side;
 setRegion(item.studyRegion);
}

function setSide(side){
 if(!['both','right','left'].includes(side)||!state.ready)return;
 learningEnhancements?.clearStudyContext(true);state.side=side;state.isolated=false;state.neighbors=false;
 if(!regionContains(state.selected)){
  const b=BY_ID[state.selected],candidate=matchingSide(b,side);
  state.selected=regionContains(candidate)?candidate:defaultSelection();
 }
 updateRegionUI();setExplode(state.explode,false);applyVisibility();selectBone(state.selected,true);setView('overview');window.dispatchEvent(new CustomEvent('atlas:region-changed',{detail:{region:state.region,name:REGION_LABELS[state.region][0],side}}));
}
function setRegion(region,refit=true,options={}){
 if(!state.ready||!REGION_LABELS[region])return;
 if(!options.keepStudy)learningEnhancements?.clearStudyContext(true);
 state.region=region;state.isolated=false;state.neighbors=false;
 if(!regionContains(state.selected))state.selected=defaultSelection();
 updateRegionUI();setExplode(state.explode,false);applyVisibility();selectBone(state.selected,true);if(refit)setView('overview');if(!options.keepStudy)window.dispatchEvent(new CustomEvent('atlas:region-changed',{detail:{region,name:REGION_LABELS[region][0],side:state.side}}));invalidate();
}

const VIEWS={overview:{dir:[1,.9,1.18],up:[0,1,0],name:'立体视角'},dorsal:{dir:[0,1,.001],up:[0,0,1],name:'足背 · 从上往下看'},plantar:{dir:[0,-1,.001],up:[0,0,1],name:'足底 · 从下往上看'},medial:{dir:[1,.04,0],up:[0,1,0],name:'内侧 · 拇趾侧'},lateral:{dir:[-1,.04,0],up:[0,1,0],name:'外侧 · 小趾侧'},front:{dir:[0,.1,1],up:[0,1,0],name:'趾端 · 朝向脚跟'},back:{dir:[0,.08,-1],up:[0,1,0],name:'后面 · 从后往前看'}};
function setView(name){invalidate();
 if(!state.ready||!VIEWS[name])return;
 const v={...VIEWS[name],dir:[...VIEWS[name].dir]},damping=controls.enableDamping,upper=UPPER_REGIONS.has(state.region),globalSide=FIXED_REGIONS.has(state.region)||state.side==='both'||['body','head','thorax','auditory'].includes(state.region);
 if(name==='overview'){
  if(state.region==='leg')v.dir=[-1,.85,1.35];
  if(upper)v.dir=['lumbar','lumbosacral'].includes(state.region)?[-.9,.32,1.6]:[-.48,.18,1.9];
  if(state.region==='hip')v.dir=[-1,.24,1.6];if(['cervical','thoracic','spine','head'].includes(state.region))v.dir=[-.85,.22,1.6];if(['hand','wrist'].includes(state.region))v.dir=[-.3,.05,1.8];
  if(state.side==='left'&&!FIXED_REGIONS.has(state.region))v.dir[0]*=-1;
 }
 if(name==='medial'||name==='lateral'){
  if(globalSide)v.name=name==='medial'?'人体左面 · 从左侧看':'人体右面 · 从右侧看';
  else{if(state.side==='left')v.dir[0]*=-1;v.name=(state.side==='left'?'左侧肢体 · ':'右侧肢体 · ')+(name==='medial'?'内侧朝向身体中线':'外侧远离身体中线');}
 }
 if(upper){if(name==='front'){v.dir=[0,.015,1];v.name='正面 · 人体右侧在画面左边';}if(name==='dorsal')v.name='上方 · 从上往下看';if(name==='plantar')v.name='下方 · 从下往上看';}
 cameraTween=null;controls.enableDamping=false;controls.update();state.view=name;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('viewBadge').lastElementChild.textContent=v.name;
 try{fitToContent(false,new THREE.Vector3(...v.dir),new THREE.Vector3(...v.up));}finally{controls.enableDamping=damping;}
}
function scopedFocusBox(box,onlySelected){
 if(state.isolated||onlySelected||state.explode!==0||[...bones.values()].some(isManuallyMoved))return;
 if(!['ankle','knee','hip','shoulder','elbow','wrist'].includes(state.region))return;
 const visible=[...bones].filter(([id,b])=>b.visible);
 box.makeEmpty();
 for(const [id,b]of visible){
  const data=BY_ID[id],bounds=new THREE.Box3().setFromObject(b);
  if(state.region==='ankle'){if(data.group==='leg')bounds.max.y=Math.min(bounds.max.y,b.userData.home.y+b.geometry.boundingBox.min.y+145);}
  if(state.region==='knee'){
   if(data.baseId==='femur')bounds.max.y=bounds.min.y+155;
   if(['tibia','fibula'].includes(data.baseId))bounds.min.y=bounds.max.y-150;
  }
  if(state.region==='hip'&&data.baseId==='femur')bounds.min.y=bounds.max.y-180;
  if(state.region==='shoulder'&&data.baseId==='humerus')bounds.min.y=bounds.max.y-170;
  if(state.region==='elbow'){if(data.baseId==='humerus')bounds.max.y=bounds.min.y+130;else bounds.min.y=bounds.max.y-130;}
  if(state.region==='wrist'&&['radius','ulna'].includes(data.baseId))bounds.max.y=bounds.min.y+100;
  box.union(bounds);
 }
 box.expandByScalar(10);
}

function syncCameraUp(){if(!controls)return;controls._quat.setFromUnitVectors(camera.up,new THREE.Vector3(0,1,0));controls._quatInverse.copy(controls._quat).invert();}
