function zoom(factor){if(!state.ready)return;cameraTween=null;const delta=camera.position.clone().sub(controls.target).multiplyScalar(factor);if(delta.length()>controls.minDistance&&delta.length()<controls.maxDistance)camera.position.copy(controls.target).add(delta);controls.update();}
function pointerCoords(e){const r=viewport.getBoundingClientRect();mouse.set(((e.clientX-r.left)/r.width)*2-1,-((e.clientY-r.top)/r.height)*2+1);return r;}
function pick(e){camera.updateMatrixWorld(true);scene.updateMatrixWorld(true);pointerCoords(e);raycaster.setFromCamera(mouse,camera);return raycaster.intersectObjects([...bones.values()].filter(b=>b.visible),false)[0]||null;}
