async function loadModel(){const loader=new GLTFLoader();let gltf;if(window.FOOT_ATLAS_EMBEDDED){const raw=atob(window.FOOT_ATLAS_EMBEDDED),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);$('loadingProgress').style.width='65%';gltf=await loader.parseAsync(bytes.buffer,'');}else{gltf=await loader.loadAsync((window.ATLAS_RESOURCE_BASE||'./')+'assets/fullbody.glb',e=>{if(e.total)$('loadingProgress').style.width=(15+e.loaded/e.total*60)+'%';});}gltf.scene.updateMatrixWorld(true);gltf.scene.traverse(node=>{if(!node.isMesh)return;const id=node.name;if(!BY_ID[id])throw new Error(`未识别的源网格名称：${id}`);node.geometry.computeBoundingBox();const b=new THREE.Mesh(node.geometry,makeBoneMaterial());b.name=id;node.matrixWorld.decompose(b.position,b.quaternion,b.scale);if(b.quaternion.angleTo(new THREE.Quaternion())>1e-5||b.scale.distanceTo(new THREE.Vector3(1,1,1))>1e-5)throw new Error('源模型包含未烘焙变换');b.castShadow=true;b.receiveShadow=true;b.userData.home=b.position.clone();b.userData.offset=new THREE.Vector3();b.userData.explosion=explosionVector(id,b.position);bones.set(id,b);modelRoot.add(b);const ghost=new THREE.Mesh(b.geometry,new THREE.MeshBasicMaterial({color:'#7da38b',transparent:true,opacity:.1,depthWrite:false,wireframe:false}));ghost.position.copy(b.position);ghost.visible=false;ghost.renderOrder=-1;scene.add(ghost);ghosts.set(id,ghost);const guideGeo=new THREE.BufferGeometry().setFromPoints([b.position.clone(),b.position.clone()]),line=new THREE.Line(guideGeo,new THREE.LineDashedMaterial({color:'#7b9a7c',transparent:true,opacity:.38,dashSize:2,gapSize:2.5,depthWrite:false}));line.visible=false;scene.add(line);guides.set(id,line);});if(bones.size!==210||BONES.some(b=>!bones.has(b.id)))throw new Error(`模型不完整：需要210块，实际${bones.size}块`);const tris=[...bones.values()].reduce((n,b)=>n+(b.geometry.index?b.geometry.index.count:b.geometry.attributes.position.count)/3,0);if(tris!==534003)throw new Error(`源网格校验未通过：${tris}个三角形`);state.ready=true;$('loadingProgress').style.width='100%';$('renderStatus').textContent=`WebGL 2 · ${tris.toLocaleString('en-US')} 面`;selectBone('sternum');resize();setRegion('body');$('loading').classList.add('done');setTimeout(()=>{$('loading').hidden=true;},500);}

function syncAOProjection(){
 if(!aoPass)return;
 const u=aoPass.ssaoMaterial.uniforms;
 u.cameraNear.value=camera.near;u.cameraFar.value=camera.far;
 u.cameraProjectionMatrix.value.copy(camera.projectionMatrix);
 u.cameraInverseProjectionMatrix.value.copy(camera.projectionMatrixInverse);
 aoPass.depthRenderMaterial.uniforms.cameraNear.value=camera.near;
 aoPass.depthRenderMaterial.uniforms.cameraFar.value=camera.far;
}

